package com.caregiver.notes;
import com.caregiver.recipient.RecipientNotFoundException; import jakarta.validation.ConstraintViolationException; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.http.*; import org.springframework.http.converter.HttpMessageNotReadableException; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.*;
@RestControllerAdvice(basePackageClasses=NoteController.class) public class NoteApiExceptionHandler{
 @ExceptionHandler({NoteNotFoundException.class,RecipientNotFoundException.class}) public ResponseEntity<Map<String,Object>> notFound(RuntimeException e){return error(HttpStatus.NOT_FOUND,"NOT_FOUND",e.getMessage());}
 @ExceptionHandler(MethodArgumentNotValidException.class) public ResponseEntity<Map<String,Object>> invalid(MethodArgumentNotValidException e){Map<String,String> f=new LinkedHashMap<>();e.getBindingResult().getFieldErrors().forEach(x->f.putIfAbsent(x.getField(),x.getDefaultMessage()));return ResponseEntity.badRequest().body(Map.of("timestamp",Instant.now().toString(),"status",400,"code","VALIDATION_ERROR","message","Request validation failed.","fields",f));}
 @ExceptionHandler({IllegalArgumentException.class,ConstraintViolationException.class,HttpMessageNotReadableException.class}) public ResponseEntity<Map<String,Object>> bad(Exception e){return error(HttpStatus.BAD_REQUEST,"INVALID_REQUEST","Request contains invalid or inconsistent values.");}
 @ExceptionHandler(DataIntegrityViolationException.class) public ResponseEntity<Map<String,Object>> conflict(DataIntegrityViolationException e){return error(HttpStatus.CONFLICT,"NOTE_CONFLICT","A note for this recipient and date already exists, or an idempotency key was reused.");}
 private ResponseEntity<Map<String,Object>> error(HttpStatus s,String c,String m){return ResponseEntity.status(s).body(Map.of("timestamp",Instant.now().toString(),"status",s.value(),"code",c,"message",m));}
}